package hu.bankmonitor.payments.stream;

import io.swagger.v3.oas.annotations.Hidden;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;

/**
 * The one event stream, under the {@code /api} prefix the security chain opens by name.
 *
 * <p>The whole endpoint is a subscription: no path variable, no query parameter and no
 * request body, because a message says only that some Transfer changed and the browser
 * decides whether it cares. Design decision 17 has why that is one endpoint rather than one
 * per Transfer.
 *
 * <p>The path is written out again in the tests that call it, on {@code TransferController}'s
 * reasoning: a test reading the same constant as the mapping would follow a rename silently
 * instead of failing on it, and this is a path a deployed frontend has hard-coded.
 */
@RestController
class EventStreamController {

	private final TransferEventStream stream;

	EventStreamController(TransferEventStream stream) {
		this.stream = stream;
	}

	/**
	 * Opens the stream. The response ends when the client disconnects or the connection times
	 * out, and in both cases the browser reconnects and refetches — the same recovery path a
	 * first load takes.
	 *
	 * <p><b>Hidden from the OpenAPI document deliberately.</b> springdoc describes what a
	 * handler returns, and what this one returns is an unbounded {@code text/event-stream}
	 * rather than a body — left alone it publishes the {@link SseEmitter} object's own
	 * properties as the response schema, which describes a Spring class rather than this
	 * endpoint. Design decision 26 has the frontend generating its types from that document
	 * precisely because nothing in it is written by hand, so an entry that is wrong costs more
	 * there than an entry that is absent; and the frontend reads this stream with
	 * {@code EventSource}, not with a generated client.
	 */
	@Hidden
	@GetMapping(path = "/api/events/stream", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
	SseEmitter subscribe() {
		return stream.open();
	}
}
package hu.bankmonitor.payments.stream;

/**
 * One message on the stream: what happened, and to which Transfer. Nothing else.
 *
 * <p>That emptiness is the design decision the whole live-update story rests on (design
 * decision 17). A message carrying only a cache key is a message the browser cannot merge
 * into anything, reconcile against anything or need in order — so the frontend's entire
 * handling of the stream is one pure function from a frame to a list of stale query keys.
 * <em>The stream carries hints; the REST endpoint carries truth.</em>
 *
 * <p>It is the deliberate opposite of what the outbox sends. An Outbox Event carries the
 * payload a consuming service needs, because a service calling back for the amount is the
 * coupling design decision 11 rejected polling to avoid; a browser calling back for the
 * amount is a request to an API it is already holding open a connection to.
 *
 * @param type       which of the three ways the Transfer finished
 * @param transferId the Transfer the browser should consider stale
 */
public record TransferEvent(TransferEventType type, long transferId) {
}
package hu.bankmonitor.payments.stream;

/**
 * The three hints this stream carries, one per way a Transfer can finish.
 *
 * <p>A Transfer leaves {@code PENDING} exactly once and never moves again, so this is the
 * complete set. There is deliberately no hint for a Transfer being <em>requested</em>: the
 * only browser that could care is the one that submitted it, and it already knows.
 *
 * <p><b>These names are a contract with a frontend that was built first.</b> Ticket 36 wrote
 * {@code frontend/src/api/events.ts} against them before this endpoint existed, and that
 * module ignores a type it does not recognise — so a rename here is not a compile error and
 * not a runtime failure, it is a live-update feature that silently stops working. Screaming
 * case because that is how Jackson serialises an enum constant by default, which is what the
 * frontend was written to read.
 */
public enum TransferEventType {

	/** Every Check approved and the money moved. */
	TRANSFER_SETTLED,

	/** A Check said no. The reservation was released and no money moved. */
	TRANSFER_REJECTED,

	/** The Checks were not all answered in time. The reservation was released. */
	TRANSFER_EXPIRED
}
/**
 * The browser-facing event stream: one server-sent-events endpoint, and the registry of
 * browsers listening to it.
 *
 * <p>It exports no operation and no port — only the two value types a hint is made of,
 * {@link hu.bankmonitor.payments.stream.TransferEvent} and
 * {@link hu.bankmonitor.payments.stream.TransferEventType}. The endpoint, the registry and
 * the send are package-private, and nothing outside this package can reach a subscriber.
 *
 * <p>That is not tidiness. A change in {@code transfers} announces itself by publishing an
 * ordinary application event from inside its own transaction, and this slice listens for one
 * after that transaction commits. The container is the seam, which buys two things at once: a
 * hint can never arrive before the truth it points at, and the transaction that holds row
 * locks on a Transfer and two Accounts has no path to a socket — the rule
 * {@code LockedPathTouchesOnlyTheDatabaseTest} enforces, and the reason a direct call would
 * have been the wrong shape even if the ordering had somehow been safe.
 *
 * <p>Named {@code stream} rather than {@code events} because {@code outbox} already owns the
 * word: an Outbox Event is a durable row addressed to another service and carries the payload
 * that service needs, while a message here is addressed to a browser, carries a Transfer ID
 * and is gone the moment it is written. Design decision 17 has why the two are deliberately
 * asymmetric.
 */
package hu.bankmonitor.payments.stream;

